# ============================================================================
#  PC Tires - Stock cap + Postma H&C deposit-only  (patch-stock-phc.ps1)  2026-10-29
#  Run from:  C:\Users\Caleb\Documents\Claude\Projects\PCtires
#
#  STOCK
#   - Customers can't put more in the cart than TDG can ship (add + "+" button
#     capped; cart line shows a red warning if a saved cart is over). Owner exempt.
#   - Live TDG stock recheck when checkout opens AND right before the card is
#     charged. Short = nothing charged, customer told to adjust or call.
#   - Stock count skips TDG locations flagged "unavailable" (availability 100).
#  POSTMA H&C (POSTMAH&C code)
#   - Card can only pay the $50 deposit; Pay in Full is hidden. Balance by
#     e-transfer at install. Customer + internal emails say e-transfer.
#
#  Files: index.html, promo-codes.js, functions/order-core.js
#  Every anchor must match exactly once and the result must match the version
#  Claude tested byte-for-byte (MD5) BEFORE anything is written. Backups go to
#  _backups (push-pctires skips .bak files). Rollback command printed at the end.
#  Then deploy as usual:  .\push-pctires.ps1
# ============================================================================
$ErrorActionPreference = 'Stop'
$root = $PSScriptRoot; if (-not $root) { $root = (Get-Location).Path }
