$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$bak = Join-Path $root '_backups'; if (-not (Test-Path $bak)) { New-Item -ItemType Directory -Path $bak | Out-Null }
function D($b) { return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b)) }
function M($s) { $h = [System.Security.Cryptography.MD5]::Create(); return (($h.ComputeHash($utf8.GetBytes($s)) | ForEach-Object { $_.ToString('X2') }) -join '') }

$idx = [System.IO.File]::ReadAllText((Join-Path $root 'index.html'), $utf8)
