$expect = @{
  'index.html' = 'D5101B9EC5BB092C1E5F4CBA741AB63A'
  'promo-codes.js' = 'B0AB9FB08B10F7B57E3AC7C5265CC84B'
  'functions/order-core.js' = '77A0A65E7BA93EDBF0D57CC90993D412'
}
$files = @('index.html','promo-codes.js','functions/order-core.js')

# ---- pre-flight in memory: nothing is written unless EVERYTHING checks out ----
$text = @{}
foreach ($f in $files) {
  $p = Join-Path $root $f
  if (-not (Test-Path $p)) { throw "ABORT: missing $f. Nothing written." }
  $text[$f] = [System.IO.File]::ReadAllText($p, $utf8)
}
foreach ($x in $patches) {
  $f = $x[0]; $old = D $x[2]; $new = D $x[3]
  $n = ([regex]::Matches($text[$f], [regex]::Escape($old))).Count
  if ($n -ne 1) { throw "ABORT: anchor '$($x[1])' in $f found $n times (expected 1). Nothing written." }
  $text[$f] = $text[$f].Replace($old, $new)
  Write-Host "  ok  $f - $($x[1])" -ForegroundColor DarkGray
}
foreach ($f in $files) {
  $got = M $text[$f]
  if ($got -ne $expect[$f]) { throw "ABORT: $f result does not match the tested version (MD5 $got). Your local file differs from GitHub - run .\sync-pctires.ps1 and tell Claude. Nothing written." }
}
if (-not $text['index.html'].TrimEnd().EndsWith('</html>')) { throw 'ABORT: index.html would not end with </html>. Nothing written.' }

# ---- write ------------------------------------------------------------------
$rb = @()
foreach ($f in $files) {
  $p = Join-Path $root $f
  $leaf = Split-Path $p -Leaf
  Copy-Item $p (Join-Path $bak "$leaf.bak-$stamp")
  [System.IO.File]::WriteAllText($p, $text[$f], $utf8)
  Write-Host "  patched $f" -ForegroundColor Green
  $rb += "Copy-Item _backups\$leaf.bak-$stamp $($f.Replace('/','\')) -Force"
}
Write-Host ''
Write-Host 'Done - all 3 files match the tested version. Deploy with:  .\push-pctires.ps1' -ForegroundColor Cyan
Write-Host ('Rollback:  ' + ($rb -join '; ')) -ForegroundColor DarkGray
